--[=[
	@class DotEnv

	环境变量模块
]=]
local DotEnv = {}
DotEnv.__index = DotEnv

-- 获取储存开发选项的目录，放在 'ReplicatedStorage' 下面
DotEnv.OptionsFolder = ".envPlayers"

local localUserId = nil

-- get studio user id
if game["Run Service"]:IsStudio() then
	local function updateUserId()
		for i = 1, 20, 1 do
			local ModuleScript = game.ReplicatedStorage:FindFirstChild(".envUserInfo")
			if ModuleScript then
				localUserId = require(ModuleScript).UserId
				break
			end
			wait()
		end
	end

	if game["Run Service"]:IsClient() then
		localUserId = game.Players.LocalPlayer.UserId
		if localUserId < 0 then
			updateUserId()
		end
	else
		updateUserId()
	end
end

-- 获取储存开发选项的ModuleScript
local function getUserModuleScript(userId)
	local folderDev = game.ReplicatedStorage:FindFirstChild(DotEnv.OptionsFolder)
	if not folderDev then
		return
	end

	local userModuleScript = folderDev:FindFirstChild(tostring(userId))
	return userModuleScript
end

-- 获取通用env 配置
local function getDefaultModuleScript()
	local folderDev = game.ReplicatedStorage:FindFirstChild(DotEnv.OptionsFolder)
	if not folderDev then
		return
	end

	local default = folderDev:FindFirstChild("default")
	return default
end

function DotEnv.GetEnv()
	local defaultEnv
	local userEnv

	local result = {}

	local defaultModuleScript = getDefaultModuleScript()
	if defaultModuleScript then
		defaultEnv = require(defaultModuleScript)
		for key, value in pairs(defaultEnv) do
			result[key] = value
		end
	end

	local userModuleScript = getUserModuleScript(localUserId)
	if userModuleScript then
		userEnv = require(userModuleScript)
		for key, value in pairs(userEnv) do
			result[key] = value
		end
	end

	return result
end

--[=[
	是否允许指定选项

	上线后的游戏返回 false

	未找到值返回 false


	@param key string -- 指定选项的key
]=]
function DotEnv.IsEnable(key: string): boolean
	local value = DotEnv.GetValue(key)
	return value == true
end

--[=[
	获取指定选项的值

	上线后的游戏返回 nil

	未找到值返回 nil

	@param key string -- 指定选项的key
]=]
function DotEnv.GetValue(key: string): boolean
	if not game["Run Service"]:IsStudio() then
		return nil
	end

	local debugOptions = DotEnv.GetEnv()

	if debugOptions then
		local value = debugOptions[key]
		return value
	end
end

-- 获取调试用户ID
DotEnv.GetUserId = function()
	return localUserId
end

return DotEnv
